export const DEFAULT_BACKEND_URL = 'http://localhost:5000';

export const getBackendUrl = () => {
    return localStorage.getItem('gee_backend_url') || DEFAULT_BACKEND_URL;
};

// Helper to convert {lat, lng}[] or {lat, lng}[][] to [lng, lat] arrays recursively
const convertToGeoJsonCoords = (boundary: any): any => {
    if (!Array.isArray(boundary)) return [];

    // Check if it's a point {lat, lng}
    if (boundary.length > 0 && typeof boundary[0] === 'object' && 'lat' in boundary[0]) {
         const coords = boundary.map((p: any) => [p.lng, p.lat]);
         // Close loop if needed
         if (coords.length > 0 && (coords[0][0] !== coords[coords.length-1][0] || coords[0][1] !== coords[coords.length-1][1])) {
             coords.push(coords[0]);
         }
         return coords;
    }

    // It's likely an array of paths (MultiPolygon)
    return boundary.map(b => convertToGeoJsonCoords(b));
};

// Map Layer Tile Fetcher
export const fetchGeeLayer = async (
    layer: 'ndvi' | 'lst' | 'elevation' | 'soil',
    boundary: any,
    backendUrl: string
): Promise<string | null> => {
    try {
        const polygonCoords = convertToGeoJsonCoords(boundary);

        // Setup timeout (5 seconds)
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 5000);

        const response = await fetch(`${backendUrl}/api/get-layer`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                layer: layer,
                polygon: polygonCoords
            }),
            signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
            // Silently fail for backend errors to fallback to UI default
            return null;
        }

        const data = await response.json();
        return data.url; 

    } catch (error: any) {
        // Only log if it's NOT a connection/timeout error to keep console clean
        if (error.name !== 'AbortError' && !error.message?.includes('Failed to fetch')) {
            console.error("GEE Layer Error:", error);
        }
        return null;
    }
};

// Statistics / Time Series Fetcher
export interface GeeTimeSeriesPoint {
    date: string;
    value: number;
}

export const fetchGeeTimeSeries = async (
    boundary: any,
    backendUrl: string
): Promise<GeeTimeSeriesPoint[] | null> => {
    try {
        const polygonCoords = convertToGeoJsonCoords(boundary);

        // Setup timeout (5 seconds)
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 5000);

        const response = await fetch(`${backendUrl}/api/get-stats`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                layer: 'ndvi', // Currently defaulting to NDVI stats
                polygon: polygonCoords
            }),
            signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
            return null;
        }

        const data = await response.json();
        return data as GeeTimeSeriesPoint[];

    } catch (error: any) {
        // Only log if it's NOT a connection/timeout error to keep console clean
        if (error.name !== 'AbortError' && !error.message?.includes('Failed to fetch')) {
            console.error("GEE Stats Error:", error);
        }
        return null;
    }
};

import React, { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useParcels, Parcel } from '../context/ParcelContext';
import { fetchFieldWeather, WeatherData, getWeatherLabel, getCoordinates } from '../utils/weatherService';
import { generateMockNdviHistory, NdviPoint, getNdviColor } from '../utils/ndviService';
import { getApiKey } from '../utils/agromonitoring.ts';
import { getBackendUrl, fetchGeeLayer, fetchGeeTimeSeries } from '../utils/geeService';
import { ArrowLeft, Wind, Droplets, Thermometer, CloudRain, Sun, Cloud, CloudLightning, Snowflake, Calendar, MapPin, Sprout, Navigation, Layers, Satellite, Activity, Info, AlertTriangle, Settings as SettingsIcon, Mountain, FlaskConical, RefreshCw, Server, Save, Cloud as CloudIcon, Database } from 'lucide-react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Bar, ComposedChart, Line, LineChart, ReferenceLine } from 'recharts';

export const FieldDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { parcels, updateParcel } = useParcels();
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [loading, setLoading] = useState(true);

  // Data State
  const [ndviHistory, setNdviHistory] = useState<NdviPoint[]>([]);
  const [loadingStats, setLoadingStats] = useState(false);
  const [dataSource, setDataSource] = useState<'mock' | 'gee' | 'saved'>('mock');

  // Find the parcel
  const parcel = parcels.find(p => p.id === id);

  // Helper to fetch GEE data and save it
  const fetchAndSaveStats = async (currentParcel: Parcel) => {
      if (!currentParcel.boundary) return;

      setLoadingStats(true);
      try {
          const backendUrl = getBackendUrl();
          // Use the service which now handles timeouts and errors gracefully
          const realData = await fetchGeeTimeSeries(currentParcel.boundary, backendUrl);

          if (realData && realData.length > 0) {
              setNdviHistory(realData);
              setDataSource('gee');

              // Cache the result to Firestore so it persists across logins
              await updateParcel(currentParcel.id, { 
                  ndviHistory: realData,
                  lastAgroSync: Date.now() 
              });
          } else {
              // Fallback: Use saved if available, else Mock
              if (currentParcel.ndviHistory && currentParcel.ndviHistory.length > 0) {
                  setNdviHistory(currentParcel.ndviHistory);
                  setDataSource('saved');
              } else {
                  setNdviHistory(generateMockNdviHistory(currentParcel.date, currentParcel.crop));
                  setDataSource('mock');
              }
          }
      } catch(e) {
          // Silent fallback
          console.debug("Offline/Fallback mode activated for stats.");
          if (currentParcel.ndviHistory && currentParcel.ndviHistory.length > 0) {
               setNdviHistory(currentParcel.ndviHistory);
               setDataSource('saved');
          } else {
               setNdviHistory(generateMockNdviHistory(currentParcel.date, currentParcel.crop));
               setDataSource('mock');
          }
      }
      setLoadingStats(false);
  };

  useEffect(() => {
    const initData = async () => {
        if (!parcel) return;

        const { lat, lng } = getCoordinates(parcel.location);

        // 1. Load Weather
        fetchFieldWeather(lat, lng)
            .then(data => {
                setWeather(data);
                setLoading(false);
            })
            .catch((err) => {
                console.warn("Weather load failed:", err);
                setLoading(false);
            });

        // 2. Load Stats
        // Check if we have saved data first (Fast Load)
        if (parcel.ndviHistory && parcel.ndviHistory.length > 0) {
            setNdviHistory(parcel.ndviHistory);
            setDataSource('saved');
        } else {
            // If no data, try to fetch
            fetchAndSaveStats(parcel);
        }
    };

    initData();
  }, [parcel?.id]); // Only re-run if ID changes to prevent loops

  if (!parcel) {
    return (
      <div className="flex flex-col items-center justify-center h-full space-y-4">
        <h2 className="text-xl font-bold text-gray-800">Field Not Found</h2>
        <button onClick={() => navigate('/dashboard')} className="text-emerald-600 hover:underline">Return to Dashboard</button>
      </div>
    );
  }

  const getWeatherIcon = (code: number, size = 32) => {
    if (code === 0 || code === 1) return <Sun className="text-amber-500" size={size} />;
    if (code === 2 || code === 3) return <Cloud className="text-gray-500" size={size} />;
    if (code >= 51 && code <= 67) return <CloudRain className="text-blue-400" size={size} />;
    if (code >= 71 && code <= 77) return <Snowflake className="text-cyan-400" size={size} />;
    if (code >= 95) return <CloudLightning className="text-purple-500" size={size} />;
    return <Cloud className="text-gray-400" size={size} />;
  };

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return new Intl.DateTimeFormat('en-DK', { weekday: 'short', day: 'numeric' }).format(date);
  };

  const formatShortDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return new Intl.DateTimeFormat('en-DK', { weekday: 'short' }).format(date);
  };

  const getCardinalDirection = (deg: number) => {
    const val = Math.floor((deg / 22.5) + 0.5);
    const arr = ["N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE", "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW"];
    return arr[val % 16];
  };

  const currentNdvi = ndviHistory.length > 0 ? ndviHistory[ndviHistory.length - 1].value : 0;

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <button 
            onClick={() => navigate('/dashboard')}
            className="p-2 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 text-gray-600 transition-colors"
        >
            <ArrowLeft size={20} />
        </button>
        <div>
            <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
                {parcel.name} 
                <span className="text-sm font-normal text-gray-500 bg-gray-100 px-2 py-0.5 rounded-full border border-gray-200">
                    {parcel.size} ha
                </span>
            </h1>
            <p className="text-sm text-gray-500 flex items-center gap-1.5 mt-1">
                <MapPin size={14} /> {parcel.location}
            </p>
        </div>
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Column: Field Overview & Map */}
        <div className="space-y-6">

            {/* Field Monitor Map */}
            <FieldMonitorMap parcel={parcel} />

            <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6">
                <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2">
                    <Sprout className="text-emerald-600" size={20}/> Crop Status
                </h3>
                <div className="space-y-4">
                    <div className="flex justify-between items-center py-2 border-b border-gray-50">
                        <span className="text-gray-500">Crop Type</span>
                        <span className="font-medium text-gray-900">{parcel.crop}</span>
                    </div>
                    <div className="flex justify-between items-center py-2 border-b border-gray-50">
                        <span className="text-gray-500">Sowing Date</span>
                        <span className="font-medium text-gray-900">{parcel.date}</span>
                    </div>
                    <div className="flex justify-between items-center py-2 border-b border-gray-50">
                        <span className="text-gray-500">Latest NDVI</span>
                        <span className="font-bold text-gray-900 flex items-center gap-2">
                           <span className="w-2 h-2 rounded-full" style={{ backgroundColor: getNdviColor(currentNdvi) }}></span>
                           {currentNdvi.toFixed(2)}
                        </span>
                    </div>
                </div>
            </div>

            <div className="bg-gradient-to-br from-emerald-800 to-emerald-900 rounded-xl shadow-lg p-6 text-white">
                <h3 className="font-bold opacity-90 mb-1">Agronomist Note</h3>
                <p className="text-emerald-100 text-sm leading-relaxed">
                   {currentNdvi > 0.6 
                     ? `Vegetation index (NDVI: ${currentNdvi.toFixed(2)}) indicates vigorous growth. Biomass development is consistent with the planting date.`
                     : `Vegetation index is currently ${currentNdvi.toFixed(2)}. Monitor areas with yellow overlay for potential nutrient stress or waterlogging.`
                   }
                </p>
            </div>
        </div>

        {/* Right Column: Scientific Weather & Forecast */}
        <div className="lg:col-span-2 space-y-6">

            {/* NDVI Chart Section */}
            <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6 relative">
                <div className="flex justify-between items-center mb-6">
                    <div>
                        <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                            <Activity className="text-emerald-600" size={20} /> Vegetation Index Trend
                        </h2>
                        <div className="flex items-center gap-2 mt-1">
                            <span className={`text-xs px-2 py-0.5 rounded-full flex items-center gap-1 border transition-colors ${
                                dataSource === 'gee' ? 'bg-indigo-50 text-indigo-700 border-indigo-100' : 
                                dataSource === 'saved' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' :
                                'bg-gray-100 text-gray-600 border-gray-200'
                            }`}>
                                {dataSource === 'gee' && <Server size={10} />}
                                {dataSource === 'saved' && <Database size={10} />}
                                {dataSource === 'mock' && <Info size={10} />}

                                {dataSource === 'gee' && 'Live from Earth Engine'}
                                {dataSource === 'saved' && 'Saved to Cloud'}
                                {dataSource === 'mock' && 'Simulated Data'}
                            </span>
                            {dataSource === 'saved' && parcel.lastAgroSync && (
                                <span className="text-[10px] text-gray-400">
                                    Last update: {new Date(parcel.lastAgroSync).toLocaleDateString()}
                                </span>
                            )}
                        </div>
                    </div>

                    <div className="flex items-center gap-3">
                        <button 
                            onClick={() => fetchAndSaveStats(parcel)}
                            disabled={loadingStats}
                            className="p-1.5 text-gray-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors disabled:opacity-50"
                            title="Force Refresh Data from GEE"
                        >
                            <RefreshCw size={16} className={loadingStats ? "animate-spin" : ""} />
                        </button>
                    </div>
                </div>

                {loadingStats && dataSource !== 'saved' ? (
                     <div className="h-64 w-full flex flex-col items-center justify-center text-gray-400">
                        <RefreshCw className="animate-spin mb-2" size={24} />
                        <span className="text-sm">Calculating stats on Earth Engine...</span>
                     </div>
                ) : (
                    <div className="h-64 w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={ndviHistory} margin={{ top: 5, right: 5, bottom: 5, left: 0 }}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                                <XAxis 
                                    dataKey="date" 
                                    tickFormatter={formatShortDate} 
                                    tick={{fill: '#9ca3af', fontSize: 10}} 
                                    axisLine={false} 
                                    tickLine={false} 
                                    minTickGap={30}
                                />
                                <YAxis 
                                    domain={[0, 1]} 
                                    tick={{fill: '#9ca3af', fontSize: 10}} 
                                    axisLine={false} 
                                    tickLine={false} 
                                />
                                <Tooltip 
                                    contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
                                    labelFormatter={(label) => formatDate(label as string)}
                                />
                                <ReferenceLine y={0.2} stroke="#a1662f" strokeDasharray="3 3" label={{ value: 'Soil', position: 'insideLeft', fill: '#a1662f', fontSize: 10 }} />
                                <ReferenceLine y={0.8} stroke="#22c55e" strokeDasharray="3 3" label={{ value: 'Dense', position: 'insideLeft', fill: '#22c55e', fontSize: 10 }} />
                                <Line 
                                    type="monotone" 
                                    dataKey="value" 
                                    stroke="#10b981" 
                                    strokeWidth={3} 
                                    dot={{r: 4, fill: '#10b981', strokeWidth: 2, stroke: '#fff'}} 
                                    activeDot={{r: 6}} 
                                />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                )}
            </div>

            {/* Current Weather Card */}
            <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6">
                <div className="flex justify-between items-start mb-6">
                    <div>
                        <h2 className="text-lg font-bold text-gray-900">Current Conditions</h2>
                        <p className="text-sm text-gray-500">Source: DMI / Open-Meteo</p>
                    </div>
                    <div className="bg-blue-50 text-blue-700 px-3 py-1 rounded-full text-xs font-semibold">
                        Live Data
                    </div>
                </div>

                {loading ? (
                    <div className="h-40 flex items-center justify-center">
                        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-emerald-600"></div>
                    </div>
                ) : weather ? (
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                        {/* Weather items ... */}
                         <div className="col-span-2 md:col-span-1 flex flex-col items-center justify-center p-4 bg-gray-50 rounded-xl">
                            {getWeatherIcon(weather.current.weatherCode)}
                            <span className="mt-2 text-3xl font-bold text-gray-900">{weather.current.temperature}°</span>
                            <span className="text-sm text-gray-500 text-center">{getWeatherLabel(weather.current.weatherCode)}</span>
                        </div>

                        <div className="col-span-1 flex flex-col items-center justify-center p-4 bg-gray-50 rounded-xl relative overflow-hidden">
                           <div className="absolute top-2 left-3 text-xs font-bold text-gray-400 uppercase">Wind</div>
                           <div className="relative w-20 h-20 border-2 border-gray-200 rounded-full flex items-center justify-center mt-2">
                              <span className="absolute -top-1.5 text-[8px] font-bold text-gray-400 bg-gray-50 px-1">N</span>
                              <span className="absolute -right-1.5 text-[8px] font-bold text-gray-400 bg-gray-50 px-1">E</span>
                              <span className="absolute -bottom-1.5 text-[8px] font-bold text-gray-400 bg-gray-50 px-1">S</span>
                              <span className="absolute -left-1.5 text-[8px] font-bold text-gray-400 bg-gray-50 px-1">W</span>
                              <div 
                                style={{ transform: `rotate(${weather.current.windDirection}deg)` }}
                                className="w-full h-full flex items-center justify-center transition-transform duration-1000 ease-out"
                              >
                                  <Navigation size={24} className="text-emerald-600 fill-emerald-600 mb-6" />
                              </div>
                           </div>
                           <div className="text-center mt-2">
                               <div className="text-lg font-bold text-gray-900">{weather.current.windSpeed} <span className="text-xs font-normal text-gray-500">km/h</span></div>
                               <div className="text-xs text-emerald-700 font-medium">{getCardinalDirection(weather.current.windDirection)}</div>
                           </div>
                        </div>

                        <div className="col-span-1 flex flex-col justify-between p-4 bg-gray-50 rounded-xl space-y-1">
                             <div className="flex items-center gap-2 text-gray-500 text-sm uppercase font-bold"><Droplets size={14}/> Humidity</div>
                             <div className="flex-1 flex flex-col justify-center gap-2">
                                <span className="text-2xl font-bold text-gray-900">{weather.current.humidity}%</span>
                                <div className="w-full bg-gray-200 rounded-full h-2">
                                    <div 
                                        className="bg-blue-500 h-2 rounded-full transition-all duration-1000" 
                                        style={{ width: `${weather.current.humidity}%` }}
                                    ></div>
                                </div>
                                <span className="text-xs text-gray-400">Dew Point: {(weather.current.temperature - ((100 - weather.current.humidity)/5)).toFixed(1)}°</span>
                             </div>
                        </div>

                         <div className="flex flex-col justify-center p-4 bg-gray-50 rounded-xl space-y-1">
                             <div className="flex items-center gap-2 text-gray-500 text-sm uppercase font-bold"><Thermometer size={14}/> Soil Temp</div>
                             <div className="flex-1 flex flex-col justify-center">
                                <span className="text-2xl font-bold text-gray-900">{(weather.current.temperature - 2).toFixed(1)}°</span>
                                <span className="text-xs text-gray-400">Est. Topsoil (5cm)</span>
                             </div>
                        </div>
                    </div>
                ) : (
                    <div className="text-red-500">Failed to load weather data.</div>
                )}
            </div>

            {/* 7-Day Forecast */}
            {weather && (
                <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6 overflow-hidden">
                    <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                        <Calendar size={16} /> 7-Day Forecast
                    </h3>
                    <div className="flex overflow-x-auto pb-2 gap-4 no-scrollbar">
                        {weather.daily.map((day, idx) => (
                            <div key={idx} className="flex-shrink-0 w-28 flex flex-col items-center bg-gray-50 p-3 rounded-lg border border-gray-100">
                                <span className="text-xs font-semibold text-gray-500 mb-2">{formatShortDate(day.date)}</span>
                                <div className="mb-2">{getWeatherIcon(day.weatherCode, 28)}</div>
                                <div className="flex items-end gap-1 mb-1">
                                    <span className="text-lg font-bold text-gray-900">{Math.round(day.maxTemp)}°</span>
                                    <span className="text-xs text-gray-500 mb-1">{Math.round(day.minTemp)}°</span>
                                </div>
                                <div className="flex items-center gap-1 text-xs text-blue-600 font-medium">
                                    <Droplets size={10} />
                                    {day.rainSum}mm
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Weather Analytics Charts */}
            {weather && !loading && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Temp + Rain Chart */}
                    <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                        <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                            <Thermometer size={16} /> Temperature & Rainfall
                        </h3>
                        <div className="h-64 w-full text-xs">
                            <ResponsiveContainer width="100%" height="100%">
                                <ComposedChart data={weather.daily}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                                    <XAxis dataKey="date" tickFormatter={formatShortDate} tick={{fill: '#9ca3af'}} axisLine={false} tickLine={false} />
                                    <YAxis yAxisId="left" orientation="left" tick={{fill: '#9ca3af'}} axisLine={false} tickLine={false} unit="°" />
                                    <YAxis yAxisId="right" orientation="right" tick={{fill: '#9ca3af'}} axisLine={false} tickLine={false} unit="mm" />
                                    <Tooltip 
                                        contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
                                        labelFormatter={(label) => formatDate(label as string)}
                                    />
                                    <Bar yAxisId="right" dataKey="rainSum" name="Rain" fill="#93c5fd" radius={[4, 4, 0, 0]} barSize={20} />
                                    <Line yAxisId="left" type="monotone" dataKey="maxTemp" name="Max Temp" stroke="#f59e0b" strokeWidth={2} dot={{r: 3}} />
                                    <Line yAxisId="left" type="monotone" dataKey="minTemp" name="Min Temp" stroke="#60a5fa" strokeWidth={2} dot={{r: 3}} />
                                </ComposedChart>
                            </ResponsiveContainer>
                        </div>
                    </div>

                    {/* Wind & Evapotranspiration */}
                    <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                        <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                            <Wind size={16} /> Wind Speed & Evapotranspiration
                        </h3>
                        <div className="h-64 w-full text-xs">
                             <ResponsiveContainer width="100%" height="100%">
                                <AreaChart data={weather.daily}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                                    <XAxis dataKey="date" tickFormatter={formatShortDate} tick={{fill: '#9ca3af'}} axisLine={false} tickLine={false} />
                                    <YAxis tick={{fill: '#9ca3af'}} axisLine={false} tickLine={false} />
                                    <Tooltip 
                                        contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
                                        labelFormatter={(label) => formatDate(label as string)}
                                    />
                                    <Area type="monotone" dataKey="maxWind" name="Max Wind (km/h)" stackId="1" stroke="#10b981" fill="#d1fae5" />
                                    <Area type="monotone" dataKey="evapotranspiration" name="Evapotranspiration (mm)" stackId="2" stroke="#8b5cf6" fill="#ede9fe" />
                                </AreaChart>
                            </ResponsiveContainer>
                        </div>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

// ----------------------------------------------------------------------
// Field Monitor Map Component
// ----------------------------------------------------------------------

type LayerType = 'satellite' | 'ndvi' | 'lst' | 'elevation' | 'soil';

const FieldMonitorMap: React.FC<{ parcel: Parcel }> = ({ parcel }) => {
    const mapRef = useRef<HTMLDivElement>(null);
    const mapInstanceRef = useRef<any>(null);
    const polygonRef = useRef<any>(null);

    const [layer, setLayer] = useState<LayerType>('satellite');
    const [tileUrl, setTileUrl] = useState<string | null>(null);
    const [loadingLayer, setLoadingLayer] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Fetch Tile URL from Backend when layer changes
    useEffect(() => {
        const loadLayer = async () => {
            if (layer === 'satellite' || !parcel.boundary) {
                setTileUrl(null);
                setError(null);
                return;
            }

            setLoadingLayer(true);
            setError(null);

            const backendUrl = getBackendUrl();
            const url = await fetchGeeLayer(layer, parcel.boundary, backendUrl);

            if (url) {
                setTileUrl(url);
            } else {
                // If null is returned, it means failure but likely handled by service logging or silent fail
                // We show a user friendly message only if we are sure it's an error we want them to see
                // For now, if backend is offline, we just don't show the layer
                // setError("Connection failed"); // Removed to prevent UI clutter if just offline
                setTileUrl(null);
            }
            setLoadingLayer(false);
        };

        loadLayer();
    }, [layer, parcel]);

    // Map Rendering Logic
    useEffect(() => {
        if (!mapRef.current || !window.google?.maps || !parcel.boundary) return;

        // Initialize Map
        if (!mapInstanceRef.current) {
            const { lat, lng } = getCoordinates(parcel.location);
            mapInstanceRef.current = new window.google.maps.Map(mapRef.current, {
                center: { lat, lng },
                zoom: 14,
                mapTypeId: 'hybrid',
                disableDefaultUI: true,
                zoomControl: true,
                draggable: false, 
                scrollwheel: false,
            });
        }

        const map = mapInstanceRef.current;

        // Cleanup
        if (polygonRef.current) polygonRef.current.setMap(null);
        if (map.overlayMapTypes.length > 0) map.overlayMapTypes.clear();

        // Polygon Styles
        const polyOptions = {
            paths: parcel.boundary,
            strokeColor: '#fff',
            strokeOpacity: 0.9,
            strokeWeight: 2,
            fillColor: '#000',
            fillOpacity: 0, 
        };

        const polygon = new window.google.maps.Polygon(polyOptions);
        polygon.setMap(map);
        polygonRef.current = polygon;

        // Fit bounds
        const bounds = new window.google.maps.LatLngBounds();

        // Handle MultiPolygon (nested arrays) or simple Polygon
        const paths = Array.isArray(parcel.boundary[0]) ? parcel.boundary.flat() : parcel.boundary;
        paths.forEach((coord: any) => bounds.extend(coord));

        map.fitBounds(bounds);

        // Apply Custom Tile Layer (GEE)
        if (tileUrl) {
            const imageMapType = new window.google.maps.ImageMapType({
                getTileUrl: function(coord: any, zoom: any) {
                    return tileUrl
                        .replace('{x}', coord.x.toString())
                        .replace('{y}', coord.y.toString())
                        .replace('{z}', zoom.toString());
                },
                tileSize: new window.google.maps.Size(256, 256),
                opacity: 0.75,
                name: layer
            });
            map.overlayMapTypes.push(imageMapType);
        }

    }, [parcel, tileUrl, layer]);

    return (
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden flex flex-col h-[500px]">
            <div className="p-3 bg-gray-50 border-b border-gray-100 flex flex-col gap-2">
                <div className="flex justify-between items-center">
                    <h3 className="text-sm font-bold text-gray-700 flex items-center gap-2">
                        <Layers size={16} /> Field Monitor
                    </h3>
                    <button 
                        onClick={() => window.open('/#/settings', '_self')}
                        className="text-xs text-gray-500 hover:text-emerald-700 flex items-center gap-1"
                    >
                        <SettingsIcon size={12}/> Config
                    </button>
                </div>

                {/* Layer Selector */}
                <div className="flex bg-white rounded-lg border border-gray-200 p-1 overflow-x-auto no-scrollbar gap-1">
                    {[
                        { id: 'satellite', label: 'Satellite', icon: Satellite },
                        { id: 'ndvi', label: 'NDVI', icon: Sprout },
                        { id: 'lst', label: 'LST Temp', icon: Thermometer },
                        { id: 'elevation', label: 'Elevation', icon: Mountain },
                        { id: 'soil', label: 'Soil Clay', icon: FlaskConical },
                    ].map((item) => (
                        <button 
                            key={item.id}
                            onClick={() => setLayer(item.id as LayerType)}
                            className={`flex items-center gap-1.5 flex-shrink-0 px-3 py-1.5 text-xs font-medium rounded-md transition-all ${
                                layer === item.id 
                                ? 'bg-emerald-100 text-emerald-900 shadow-sm ring-1 ring-emerald-200' 
                                : 'text-gray-600 hover:bg-gray-100'
                            }`}
                        >
                            <item.icon size={12} />
                            {item.label}
                        </button>
                    ))}
                </div>
            </div>

            <div className="flex-1 relative bg-gray-100">
                {parcel.boundary ? (
                     <>
                        <div ref={mapRef} className="absolute inset-0 w-full h-full" />

                        {/* Loading Overlay */}
                        {loadingLayer && (
                            <div className="absolute top-4 right-4 bg-white/90 backdrop-blur px-3 py-1.5 rounded-full shadow text-xs font-medium flex items-center gap-2 text-emerald-700">
                                <div className="w-3 h-3 border-2 border-emerald-200 border-t-emerald-600 rounded-full animate-spin"></div>
                                Computing Layer...
                            </div>
                        )}

                        {/* Error Overlay */}
                        {error && (
                            <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-red-50 text-red-600 px-4 py-2 rounded-lg shadow-lg text-xs font-bold border border-red-200 flex flex-col items-center z-10">
                                <span className="flex items-center gap-1"><AlertTriangle size={14}/> {error}</span>
                                <span className="font-normal opacity-80 mt-1">Check Python Server</span>
                            </div>
                        )}

                        {/* Legends */}
                        {!loadingLayer && !error && (
                            <div className="absolute bottom-4 left-4 bg-white/95 backdrop-blur px-3 py-2 rounded-lg shadow border border-gray-200 text-xs z-10">
                                <div className="font-bold mb-1.5 text-gray-800 uppercase tracking-wide text-[10px]">
                                    {layer === 'satellite' ? 'Visual' : layer} Scale
                                </div>
                                <div className="flex items-center gap-2">
                                    {layer === 'ndvi' && (
                                        <>
                                            <div className="flex flex-col items-center"><span className="w-3 h-3 rounded bg-[#a1662f]"></span><span className="text-[9px] mt-0.5">Soil</span></div>
                                            <div className="flex flex-col items-center"><span className="w-3 h-3 rounded bg-[#eab308]"></span><span className="text-[9px] mt-0.5">Sparse</span></div>
                                            <div className="flex flex-col items-center"><span className="w-3 h-3 rounded bg-[#84cc16]"></span><span className="text-[9px] mt-0.5">Good</span></div>
                                            <div className="flex flex-col items-center"><span className="w-3 h-3 rounded bg-[#22c55e]"></span><span className="text-[9px] mt-0.5">Dense</span></div>
                                        </>
                                    )}
                                    {layer === 'lst' && (
                                        <>
                                            <div className="flex flex-col items-center"><span className="w-3 h-3 rounded bg-blue-500"></span><span className="text-[9px] mt-0.5">Cool</span></div>
                                            <div className="flex flex-col items-center"><span className="w-3 h-3 rounded bg-yellow-400"></span><span className="text-[9px] mt-0.5">Warm</span></div>
                                            <div className="flex flex-col items-center"><span className="w-3 h-3 rounded bg-red-500"></span><span className="text-[9px] mt-0.5">Hot</span></div>
                                        </>
                                    )}
                                    {layer === 'elevation' && (
                                         <>
                                            <div className="flex flex-col items-center"><span className="w-3 h-3 rounded bg-[#10b981]"></span><span className="text-[9px] mt-0.5">Low</span></div>
